const item = $input.first().json;

// 1. Dataset → sheet name mapping
const sheetMap = {
  "batch1_train": "batch1_train",
  "batch2_validate": "batch2_validate"
};

// 2. 設定 sheet & codebook (default to ___)
const dataset = item.Dataset;
const sheet = sheetMap[dataset];
const codebook = "暗黑襲產評論_Codebook";

// 3. LLM model
const modelsToRun = item.LLM;  // default

// 4. expand 成多筆任務 items
return modelsToRun.map(m => {
  return {
    json: {
      sheet: sheet,
      codebook : codebook,
      model_key: m,
      task_id: `${dataset}_${m}`
    }
  };
});

const systemPrompt = $('Set-up Configurations').first().json.system_prompt;
const reasonPrompt = $('Set-up Configurations').first().json.reason_llm;
const processedItems = $input.all();

return processedItems.map((item) => {
  const row = item.json;
  const place_name = row.place_name;
  const review_id = row.review_id;
  const text = row.text;
  const codebookText = row.content;

  const annotatePrompt = `你是一位Google Map評論內容標註人員，請認真依照編碼簿的規則，對每一則評論內容進行標註。如果你一次收到多則評論，請獨立標註每一則評論內容，不要受到其他評論影響。

## 編碼簿
${codebookText}

${reasonPrompt}

## 待標註評論內容 (place_name = ${place_name}, review_id = ${review_id})
${text}`;

  return {
    json: {
      review_id: row.review_id,
      sheet: row.sheet,
      model: row.model_key,
      requestBody: {
        model: "gpt-oss-120b",
        messages: [
          {
            role: "system",
            content: systemPrompt
          },
          {
            role: "user",
            content: annotatePrompt
          }
        ],
        temperature: 0,
        max_completion_tokens: 8192,
        stream: false,
        response_format: { type: "json_object" }
      }
    }
  };
});

const items = $input.all();
const out = [];
const config = $('Set-up Configurations').first().json;

function toArray(val) {
  if (Array.isArray(val)) return val;
  if (typeof val === 'string' && val.trim() !== '') {
    try { return JSON.parse(val); } catch { return []; }
  }
  return [];
}

function extractJSON(text) {
  const fenced = text.match(/```json\s*([\s\S]*?)```/);
  if (fenced) return fenced[1].trim();
  const braceMatch = text.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
  if (braceMatch) return braceMatch[1].trim();
  return null;
}

const variables = toArray(config.variables);
const allFields = [...variables];

for (const item of items) {
  const data = item.json;

  // Groq / OpenAI 回應路徑
  const content = data?.choices?.[0]?.message?.content;

  if (!content) {
    out.push({ json: { error: "No content in choices[0].message.content", raw: data } });
    continue;
  }

  const extracted = extractJSON(content);
  if (!extracted) {
    out.push({ json: { error: "No JSON found in content", content, raw: data } });
    continue;
  }

  let parsed;
  try {
    parsed = JSON.parse(extracted);
  } catch (e) {
    out.push({ json: { error: "Failed to parse JSON", content, extracted, raw: data } });
    continue;
  }

  // finishReason 檢查
  const finishReason = data?.choices?.[0]?.finish_reason;
  if (finishReason !== 'stop') {
    out.push({ json: { error: `Unexpected finish_reason: ${finishReason}`, raw: data } });
    continue;
  }

  const annotations = parsed.annotations ?? [];
  for (const ann of annotations) {
    const row = {
      review_id: $('Loop Over Items2').item.json.review_id ?? ann.review_id ?? item.json.review_id ?? null,
      model: data?.model ?? item.json.model ?? null
    };
    for (const field of allFields) {
      row[field] = ann[field] ?? null;
    }
    out.push({ json: row });
  }
}

return out;

