  const braceMatch = text.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
  if (braceMatch) return braceMatch[1].trim();
  return null;
}

const variables = toArray(config.variables);
const allFields = [...variables];

for (const item of items) {
  const data = item.json;

  const content = data?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!content) {
    out.push({ json: { error: "No content in candidates[0].content.parts[0].text", raw: data } });
    continue;
  }

  const extracted = extractJSON(content);
  if (!extracted) {
    out.push({ json: { error: "No JSON found in content", content, raw: data } });
    continue;
  }

  let parsed;
  try {
    parsed = JSON.parse(extracted);
  } catch (e) {
    out.push({ json: { error: "Failed to parse JSON", content, extracted, raw: data } });
    continue;
  }

  const annotations = parsed.annotations ?? [];
  for (let i = 0; i < annotations.length; i++) {
    const ann = annotations[i];
    const row = {
      review_id: reviewIds[i] ?? ann.review_id ?? null,
      model: $input.first().json.modelVersion ?? null
    };
    for (const field of allFields) {
      row[field] = ann[field] ?? null;
    }
    out.push({ json: row });
  }
}

return out;
